import {
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Container,
  Divider,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TablePagination,
  TextField,
  Typography,
} from '@mui/material';
import { getAuth } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import * as React from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import './ClassDetailStyles.css'; // Import the external style file

export default function Students() {
  const { className } = useParams();
  const navigate = useNavigate();

  const [searchTerm, setSearchTerm] = React.useState('');
  const [sortBy, setSortBy] = React.useState('');
  const [students, setStudents] = React.useState([]);
  const [filteredStudents, setFilteredStudents] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
  const [isClassTeacher, setIsClassTeacher] = React.useState(false);
  const [currentTeacherId, setCurrentTeacherId] = React.useState(null);

  // Class filter state
  const [classFilter, setClassFilter] = React.useState('');

  // Pagination state
  const [page, setPage] = React.useState(0);
  const [rowsPerPage, setRowsPerPage] = React.useState(10);

  // Helper function to calculate age
  const calculateAge = (dob) => {
    const birthDate = new Date(dob);
    const difference = Date.now() - birthDate.getTime();
    const ageDate = new Date(difference);
    return Math.abs(ageDate.getUTCFullYear() - 1970);
  };

  // Fetch teacher details and determine if they are a class teacher
  React.useEffect(() => {
    const fetchCurrentTeacher = async () => {
      try {
        const db = getFirestore();
        const auth = getAuth();
        const userId = auth.currentUser?.uid;

        if (!userId) {
          console.error('No user ID found.');
          return;
        }

        const teachersRef = collection(db, 'Teachers');
        const q = query(teachersRef, where('id', '==', userId));

        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const teacherDoc = querySnapshot.docs[0];
          const teacherData = teacherDoc.data();
          setCurrentTeacherId(userId);
          if (teacherData.isClassTeacher) {
            setIsClassTeacher(true);
          }
        }
      } catch (err) {
        console.error('Error fetching teacher details:', err);
      }
    };

    fetchCurrentTeacher();
  }, []);

  // Fetch students data from Firestore
  React.useEffect(() => {
    const fetchStudents = async () => {
      try {
        const db = getFirestore();
        const querySnapshot = await getDocs(collection(db, 'Students'));
        const studentsList = querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
        setStudents(studentsList);
        setFilteredStudents(studentsList);
      } catch (err) {
        setError('Error fetching students: ' + (err.message || 'Unknown error'));
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  // Filter and sort students based on search term, sorting criteria, and class filter
  React.useEffect(() => {
    let sortedStudents = students.filter((student) =>
      student.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter by class level if a class is selected
    if (classFilter) {
      sortedStudents = sortedStudents.filter((student) => student.classLevel === classFilter);
    }

    if (sortBy) {
      sortedStudents = sortedStudents.sort((a, b) => {
        if (sortBy === 'name') {
          return a.name.localeCompare(b.name);
        } else if (sortBy === 'age') {
          return calculateAge(a.dob) - calculateAge(b.dob);
        } else if (sortBy === 'classLevel') {
          const classOrder = {
            'KG 1': 1,
            'KG 2': 2,
            'Basic 1': 3,
            'Basic 2': 4,
            'Basic 3': 5,
            'Basic 4': 6,
            'Basic 5': 7,
            'Basic 6': 8,
            'Basic 7': 9,
            'Basic 8': 10,
            'Basic 9': 11,
          };
          return classOrder[a.classLevel] - classOrder[b.classLevel];
        }
        return 0;
      });
    }

    setFilteredStudents(sortedStudents);
  }, [searchTerm, sortBy, students, classFilter]);

  // Handle pagination
  const handlePageChange = (event, newPage) => {
    setPage(newPage);
  };

  const handleRowsPerPageChange = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0); // Reset to the first page whenever rows per page changes
  };

  const handleViewDetails = (student) => {
    const encodedName = encodeURIComponent(student.name);
    navigate(`details/${encodedName}`, { state: { student } });
  };

  const handleViewGrades = (student) => {
    const encodedName = encodeURIComponent(student.name);
    navigate(`grades/${encodedName}`, { state: { student, code: student.code, term: student.term } });
  };

  const handleAddStudent = () => {
    navigate('add');
  };

  const handleSortChange = (event) => {
    setSortBy(event.target.value);
  };

  // Slice the filtered students based on the current page and rows per page
  const paginatedStudents = filteredStudents.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        All Students
      </Typography>
      <TextField
        variant="outlined"
        placeholder="Search by name"
        fullWidth
        sx={{ mb: 2 }}
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <FormControl sx={{ minWidth: 120, mb: 4 }}>
        <InputLabel>Sort By</InputLabel>
        <Select value={sortBy} onChange={handleSortChange} label="Sort By">
          <MenuItem value="">None</MenuItem>
          <MenuItem value="name">Name</MenuItem>
          <MenuItem value="age">Age</MenuItem>
          <MenuItem value="classLevel">Class Level</MenuItem>
        </Select>
      </FormControl>

      {/* Class Filter Buttons */}
      <Box sx={{ mb: 4 }}>
        <Button variant="outlined" onClick={() => setClassFilter('KG 1')}>KG 1</Button>
        <Button variant="outlined" onClick={() => setClassFilter('KG 2')} sx={{ ml: 1 }}>KG 2</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 1')} sx={{ ml: 1 }}>Basic 1</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 2')} sx={{ ml: 1 }}>Basic 2</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 3')} sx={{ ml: 1 }}>Basic 3</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 4')} sx={{ ml: 1 }}>Basic 4</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 5')} sx={{ ml: 1 }}>Basic 5</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 6')} sx={{ ml: 1 }}>Basic 6</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 7')} sx={{ ml: 1 }}>Basic 7</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 8')} sx={{ ml: 1 }}>Basic 8</Button>
        <Button variant="outlined" onClick={() => setClassFilter('Basic 9')} sx={{ ml: 1 }}>Basic 9</Button>
      </Box>

      {loading ? (
        <Typography variant="h6">Loading...</Typography>
      ) : error ? (
        <Typography variant="h6" color="error">
          {error}
        </Typography>
      ) : (
        <div>
          {paginatedStudents.map((student) => (
            <Card variant="outlined" className="student-card" key={student.id} sx={{ mb: 2 }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <CardMedia
                    component="img"
                    image={student.image} // Ensure this is the path to the student's image
                    alt={`${student.name}'s photo`}
                    sx={{ width: 100, height: 100, borderRadius: '50%', mr: 2 }} // Adjust size and style
                  />
                  <Box>
                    <Typography variant="h6">{student.name}</Typography>
                    <Typography variant="body2">Class: {student.classLevel}</Typography>
                    <Typography variant="body2">Age: {calculateAge(student.dob)}</Typography>
                  </Box>
                </Box>
                <Divider sx={{ my: 2 }} />
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Button variant="outlined" onClick={() => handleViewDetails(student)}>View Details</Button>
                  <Button variant="outlined" onClick={() => handleViewGrades(student)}>View Grades</Button>
                </Box>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <TablePagination
        rowsPerPageOptions={[10, 25, 50]}
        component="div"
        count={filteredStudents.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handlePageChange}
        onRowsPerPageChange={handleRowsPerPageChange}
      />
      {isClassTeacher && (
        <Box sx={{ position: 'fixed', bottom: 16, right: 16 }}>
        <Button variant="contained" onClick={handleAddStudent}>
          Add A Student
        </Button>
        </Box>
      )}
    </Container>
  );
}
