import { Box, Button, Container, FormControl, InputLabel, MenuItem, Paper, Select, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

const calculateTotal = (scores) => {
  return Object.values(scores).reduce((total, score) => total + (score.totalScore || 0), 0);
};

const ClassSummary = () => {
  const [year, setYear] = useState('2024');
  const [term, setTerm] = useState('Term 1');
  const location = useLocation();
  const { classLevel } = location.state || {};
  const [students, setStudents] = useState([]);

  const years = Array.from(new Array(10), (val, index) => new Date().getFullYear() - index);

  // Define subject mappings based on class level
  const subjectMapping = {
    'KG 1': ['Language', 'Literacy', 'Numeracy', 'Owop', 'Creative Art'],
    'KG 2': ['Language', 'Literacy', 'Numeracy', 'Owop', 'Creative Art'],
    'Basic 1': ['English Language', 'Mathematics', 'Integrated Science', 'RME', 'Ewe', 'Creative Arts', 'Owop', 'History'],
    'Basic 2': ['English Language', 'Mathematics', 'Integrated Science', 'RME', 'Ewe', 'Creative Arts', 'Owop', 'History'],
    'Basic 3': ['English Language', 'Mathematics', 'Integrated Science', 'RME', 'Ewe', 'Creative Arts', 'Owop', 'History'],
    'Basic 4': ['English Language', 'Mathematics', 'Integrated Science', 'History', 'RME', 'Computing', 'Creative Art', 'Owop', 'Ewe', 'French'],
    'Basic 5': ['English Language', 'Mathematics', 'Integrated Science', 'History', 'RME', 'Computing', 'Creative Art', 'Owop', 'Ewe', 'French'],
    'Basic 6': ['English Language', 'Mathematics', 'Integrated Science', 'History', 'RME', 'Computing', 'Creative Art', 'Owop', 'Ewe', 'French'],
    'Basic 7': ['English Language', 'Mathematics', 'Integrated Science', 'Career Tech.', 'RME', 'Computing', 'Creative Art', 'Social Studies', 'Ewe', 'French'],
    'Basic 8': ['English Language', 'Mathematics', 'Integrated Science', 'Career Tech.', 'RME', 'Computing', 'Creative Art', 'Social Studies', 'Ewe', 'French'],
    'Basic 9': ['English Language', 'Mathematics', 'Integrated Science', 'Career Tech.', 'RME', 'Computing', 'Creative Art', 'Social Studies', 'Ewe', 'French'],
  };

  useEffect(() => {
    const fetchStudents = async () => {
      const db = getFirestore();
      const studentsRef = collection(db, 'Students');
      const q = query(
        studentsRef,
        where('classLevel', '==', classLevel)
      );
      const querySnapshot = await getDocs(q);
      const studentsData = querySnapshot.docs.map(doc => doc.data());
      setStudents(studentsData);
    };

    fetchStudents();
  }, [classLevel]);

  const getOrdinalSuffix = (i) => {
    const j = i % 10,
      k = i % 100;
    if (j === 1 && k !== 11) return 'st';
    if (j === 2 && k !== 12) return 'nd';
    if (j === 3 && k !== 13) return 'rd';
    return 'th';
  };

  const rankStudents = (students) => {
    return students.map((student, index) => ({
      ...student,
      position: `${index + 1}${getOrdinalSuffix(index + 1)}`,
    }));
  };

  const subjects = subjectMapping[classLevel] || [];
  
  const filteredStudents = students.map(student => {
    const studentScores = student.grades?.[year]?.[term] || {};
    const total = calculateTotal(subjects.reduce((acc, subject) => {
      acc[subject] = studentScores[subject] || { totalScore: 0 };
      return acc;
    }, {}));
    return { ...student, total, scores: studentScores };
  });

  const sortedStudents = filteredStudents.sort((a, b) => b.total - a.total);
  const rankedStudents = rankStudents(sortedStudents);

  const printRanking = () => {
    const printWindow = window.open('', '', 'height=600,width=800');
    printWindow.document.write('<html><head><title>Class Ranking</title>');
    printWindow.document.write('<style>');
    printWindow.document.write('table { width: 100%; border-collapse: collapse; text-align: center; }');
    printWindow.document.write('th, td { border: 1px solid black; padding: 8px; }');
    printWindow.document.write('th { background-color: #f2f2f2; }');
    printWindow.document.write('</style>');
    printWindow.document.write('</head><body >');
    printWindow.document.write('<h1>Class Summary</h1>');
    printWindow.document.write('<table>');
    printWindow.document.write('<tr><th>Position</th><th>Name</th>');
    subjects.forEach(subject => {
      printWindow.document.write(`<th>${subject}</th>`);
    });
    printWindow.document.write('<th>Total</th></tr>');
    rankedStudents.forEach(student => {
      printWindow.document.write('<tr>');
      printWindow.document.write(`<td>${student.position}</td>`);
      printWindow.document.write(`<td>${student.name}</td>`);
      subjects.forEach(subject => {
        printWindow.document.write(`<td>${student.scores[subject]?.totalScore || 0}</td>`);
      });
      printWindow.document.write(`<td>${student.total}</td>`);
      printWindow.document.write('</tr>');
    });
    printWindow.document.write('</table></body></html>');
    printWindow.document.close();
    printWindow.print();
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4, position: 'relative' }}>
      <Typography variant="h4" gutterBottom>
        Class Summary
      </Typography>
      <Box sx={{ mb: 4, display: 'flex', gap: 2 }}>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="year-select-label">Year</InputLabel>
          <Select
            labelId="year-select-label"
            id="year-select"
            value={year}
            onChange={(e) => setYear(e.target.value)}
            label="Year"
          >
            {years.map((yr) => (
              <MenuItem key={yr} value={yr}>{yr}</MenuItem>
            ))}
          </Select>
        </FormControl>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="term-select-label">Term</InputLabel>
          <Select
            labelId="term-select-label"
            id="term-select"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
            label="Term"
          >
            <MenuItem value="Term 1">Term 1</MenuItem>
            <MenuItem value="Term 2">Term 2</MenuItem>
            <MenuItem value="Term 3">Term 3</MenuItem>
          </Select>
        </FormControl>
      </Box>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              
              <TableCell align="center">Name</TableCell>
              {subjects.map(subject => (
                <TableCell key={subject} align="center">{subject}</TableCell>
              ))}
              <TableCell align="center">Total</TableCell>
              <TableCell align="center">Position</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {rankedStudents.map((student) => (
              <TableRow key={student.code}>
                <TableCell align="center">{student.name}</TableCell>
                {subjects.map(subject => (
                  <TableCell key={subject} align="center">
                    {student.scores[subject]?.totalScore || 0}
                  </TableCell>
                ))}
                <TableCell align="center">{student.total}</TableCell>
                <TableCell align="center">{student.position}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      <Button 
        variant="contained" 
        color="primary" 
        onClick={printRanking}
        sx={{ position: 'absolute', Top: 57, right: 16 }}
      >
        Print Ranking
      </Button>
    </Container>
  );
};

export default ClassSummary;
