import {
  Box,
  Button,
  Container,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import { getAuth } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, updateDoc, where } from 'firebase/firestore';
import * as React from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import PrintReportCard from './PrintReportCard';

const getGradeColor = (grade) => {
  switch (grade) {
    case 1: return 'green';
    case 2: return 'lightgreen';
    case 3: return 'yellow';
    case 4: return 'orange';
    case 5: return 'red';
    default: return 'grey';
  }
};

export default function StudentGrades() {
  const { encodedName } = useParams();
  const location = useLocation();
  const code = location.state?.code; // Retrieve the code from route state
  const [student, setStudent] = React.useState(null);
  const [term, setTerm] = React.useState('Term 1');
  const [year, setYear] = React.useState(`${new Date().getFullYear()}-${new Date().getFullYear() + 1}`);
  const [filteredGrades, setFilteredGrades] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
  const [isClassTeacher, setIsClassTeacher] = React.useState(false);
  const navigate = useNavigate();

  const years = Array.from(new Array(10), (val, index) => {
    const startYear = new Date().getFullYear() - index;
    const endYear = startYear + 1;
    return `${startYear}-${endYear}`;
  });
  

  React.useEffect(() => {
    const fetchStudentData = async () => {
      try {
        const db = getFirestore();
        const studentsRef = collection(db, 'Students');
        const q = query(studentsRef, where('code', '==', code));
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const studentDoc = querySnapshot.docs[0];
          const studentData = studentDoc.data();
          setStudent(studentData);

          // Fetch all students in the same class
          const allStudentsQuery = query(studentsRef, where('classLevel', '==', studentData.classLevel));
          const allStudentsSnapshot = await getDocs(allStudentsQuery);

          // Calculate positions for each subject
          const studentTotals = {};
          allStudentsSnapshot.forEach((doc) => {
            const data = doc.data();
            const grades = data.grades?.[year]?.[term] || {};
            Object.entries(grades).forEach(([subject, grade]) => {
              if (!studentTotals[subject]) {
                studentTotals[subject] = [];
              }
              studentTotals[subject].push({ studentId: doc.id, totalScore: grade.totalScore });
            });
          });

          // Determine positions for the current student
          const positions = {};
          Object.entries(studentTotals).forEach(([subject, totals]) => {
            totals.sort((a, b) => b.totalScore - a.totalScore);
            const currentPosition = totals.findIndex((item) => item.studentId === studentDoc.id) + 1;
            positions[subject] = currentPosition;
          });

          // Update filteredGrades with positions
          const updatedGrades = Object.entries(studentData.grades?.[year]?.[term] || {}).map(([subject, grade]) => ({
            subject,
            ...grade,
            position: positions[subject] || 'N/A'
          }));
          setFilteredGrades(updatedGrades);
        } else {
          setError('Student not found');
        }
      } catch (err) {
        setError('Error fetching student data: ' + (err.message || 'Unknown error'));
      } finally {
        setLoading(false);
      }
    };

    if (code) {
      fetchStudentData();
    }
  }, [code, year, term]);

  React.useEffect(() => {
    if (student) {
      // Update filteredGrades based on the selected term and year
      setFilteredGrades(Object.entries(student.grades?.[year]?.[term] || {}).map(([subject, grade]) => ({
        subject,
        ...grade
      })));
    }
  }, [student, year, term]);

  React.useEffect(() => {
    const fetchCurrentUser = async () => {
      try {
        const db = getFirestore();
        const currentUser = getAuth().currentUser;  // Implement this function to get the current user ID
        const teachersRef = collection(db, 'Teachers');
        const q = query(teachersRef, where('id', '==', currentUser.uid));
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const teacherData = querySnapshot.docs[0].data();
          setIsClassTeacher(teacherData.isClassTeacher);
        } else {
          setError('Current user not found');
        }
      } catch (err) {
        setError('Error fetching current user data: ' + (err.message || 'Unknown error'));
      }
    };

    fetchCurrentUser();
  }, []);
  

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>{error}</div>;
  }

  if (!student) {
    return <div>No student data available.</div>;
  }
  const handlePromotion = async () => {
    if (student) {
      try {
        const db = getFirestore();
        const studentsRef = collection(db, 'Students');
        const q = query(studentsRef, where('code', '==', code));
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
          const studentDoc = querySnapshot.docs[0];
          const studentData = studentDoc.data();
          const currentClass = studentData.classLevel;
          let nextClass = null;

          if (currentClass === 'KG 1') nextClass = 'KG 2';
          else if (currentClass === 'KG 2') nextClass = 'Basic 1';
          else if (currentClass.startsWith('Basic ')) {
            const currentLevel = parseInt(currentClass.split(' ')[1]);
            if (currentLevel >= 1 && currentLevel < 9) nextClass = `Basic ${currentLevel + 1}`;
          }

          if (nextClass) {
            await updateDoc(studentDoc.ref, { classLevel: nextClass });
            console.log('Student promoted successfully');
            navigate('/students');  // Navigate to the students list after promotion
          } else {
            console.log('Cannot promote student: No next class available');
          }
        } else {
          console.log('Student not found');
        }
      } catch (err) {
        console.error('Error promoting student:', err);
      }
    }
  };

  return (
    <Container maxWidth="lg">
      <Box my={4}>
        <Typography variant="h4" gutterBottom>
          Student Grades
        </Typography>
        <Typography variant="h6" gutterBottom>
          Name: {student.name}
        </Typography>
        <Typography variant="h6" gutterBottom>
          Class: {student.classLevel}
        </Typography>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
        <Typography variant="h4">
          Grades for {student.name}
        </Typography>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="year-select-label">Year</InputLabel>
          <Select
            labelId="year-select-label"
            id="year-select"
            value={year}
            onChange={(e) => setYear(e.target.value)}
            label="Year"
          >
            {years.map((yr) => (
              <MenuItem key={yr} value={yr}>{yr}</MenuItem>
            ))}
          </Select>
        </FormControl>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel id="term-select-label">Term</InputLabel>
          <Select
            labelId="term-select-label"
            id="term-select"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
            label="Term"
          >
            <MenuItem value="Term 1">Term 1</MenuItem>
            <MenuItem value="Term 2">Term 2</MenuItem>
            <MenuItem value="Term 3">Term 3</MenuItem>
          </Select>
        </FormControl>
      </Box>
        <TableContainer component={Paper} mt={2}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Subject</TableCell>
                <TableCell>Class Score</TableCell>
                <TableCell>Exam Score</TableCell>
                <TableCell>Total</TableCell>
                <TableCell>Grade</TableCell>
                <TableCell>Position</TableCell>
                <TableCell>Remark</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredGrades.map((grade) => (
                <TableRow key={grade.subject}>
                  <TableCell>{grade.subject}</TableCell>
                  <TableCell>{grade.classScore}</TableCell>
                  <TableCell>{grade.examScore}</TableCell>
                  <TableCell>{grade.totalScore}</TableCell>
                  <TableCell style={{ color: getGradeColor(grade.grade) }}>{grade.grade}</TableCell>
                  <TableCell>{grade.position}</TableCell>
                  <TableCell>{grade.remark}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
        <Box mt={2}>
          <PrintReportCard student={student} year={year} term={term} filteredGrades={filteredGrades} />
        </Box>
        {term === 'Term 3' && isClassTeacher && (
        <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
          <Button variant="contained" color="primary" onClick={handlePromotion}>
            Promote to Next Class
          </Button>
        </Box>
      )}
      </Box>
    </Container>
  );
} 