import FemaleIcon from '@mui/icons-material/Female';
import MaleIcon from '@mui/icons-material/Male';
import PeopleIcon from '@mui/icons-material/People';
import {
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  Typography
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { BarElement, CategoryScale, Chart as ChartJS, Legend, LinearScale, Title, Tooltip } from 'chart.js';
import { getAuth } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import React, { useEffect, useState } from 'react';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const CardStyled = styled(Card)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  padding: theme.spacing(2),
}));

export default function Home() {
  const [teacher, setTeacher] = useState(null);
  const [students, setStudents] = useState([]);
  const [totals, setTotals] = useState({ male: 0, female: 0, total: 0 });
  const [classCounts, setClassCounts] = useState({});
  const firestore = getFirestore();
  const currentUser = getAuth().currentUser;

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch the current teacher's data
        const teacherQuery = query(collection(firestore, 'Teachers'), where('id', '==', currentUser.uid));
        const teacherSnapshot = await getDocs(teacherQuery);
        const teacherData = teacherSnapshot.docs[0]?.data();
        setTeacher(teacherData);

        if (teacherData) {
          const classesToQuery = teacherData.classes || [];
          
          // Fetch students for the classes the teacher teaches
          const studentQuery = query(
            collection(firestore, 'Students'),
            where('classLevel', 'in', classesToQuery)
          );
          const studentSnapshot = await getDocs(studentQuery);
          const studentData = studentSnapshot.docs.map(doc => doc.data());
          setStudents(studentData);

          // Calculate totals and class counts
          const calculatedTotals = studentData.reduce((acc, student) => {
            acc.male += student.sex === 'Male' ? 1 : 0;
            acc.female += student.sex === 'Female' ? 1 : 0;
            acc.total += 1;

            // Count students in each class
            acc.classCounts[student.classLevel] = (acc.classCounts[student.classLevel] || 0) + 1;
            return acc;
          }, { male: 0, female: 0, total: 0, classCounts: {} });

          setTotals(calculatedTotals);
          setClassCounts(calculatedTotals.classCounts);
        }
      } catch (error) {
        console.error("Error fetching data: ", error);
      }
    };

    fetchData();
  }, [currentUser.uid, firestore]);

  const chartData = {
    labels: Object.keys(classCounts),
    datasets: [
      {
        label: 'Number of Students',
        data: Object.values(classCounts),
        backgroundColor: 'rgba(75, 192, 192, 0.6)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 1,
      },
    ],
  };

  if (!teacher) {
    return <Typography>Loading...</Typography>;
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Grid container spacing={3}>
        {/* Cards for totals */}
        <Grid item xs={12} md={4}>
          <CardStyled>
            <PeopleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Total Students</Typography>
              <Typography variant="h6">{totals.total}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
        <Grid item xs={12} md={4}>
          <CardStyled>
            <MaleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Male</Typography>
              <Typography variant="h6">{totals.male}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
        <Grid item xs={12} md={4}>
          <CardStyled>
            <FemaleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Female</Typography>
              <Typography variant="h6">{totals.female}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
      </Grid>

      {/* Chart for student distribution by class */}
      <Box sx={{ mt: 4 }}>
        <Typography variant="h5" gutterBottom>
          Students Distribution by Class
        </Typography>
        <Bar data={chartData} />
      </Box>
    </Container>
  );
}
