import {
  Box,
  Button,
  CircularProgress,
  Container,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  TextField,
  Typography
} from '@mui/material';
import Alert from '@mui/material/Alert';
import { styled } from '@mui/material/styles';
import { getAuth } from 'firebase/auth';
import { addDoc, collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import { getDownloadURL, getStorage, ref, uploadBytesResumable } from 'firebase/storage';
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { v4 as uuidv4 } from 'uuid';

const ImagePreview = styled('img')(({ theme }) => ({
  maxWidth: '150px',
  maxHeight: '150px',
  objectFit: 'cover',
  borderRadius: theme.shape.borderRadius,
}));

export default function AddStudent() {
  const [name, setName] = useState('');
  const [dob, setDob] = useState('');
  const [sex, setSex] = useState('');
  const [address, setAddress] = useState('');
  const [contact, setContact] = useState('');
  const [parentName, setParentName] = useState('');
  const [religiousAffiliation, setReligiousAffiliation] = useState('');
  const [dateOfAdmission, setDateOfAdmission] = useState('');
  const [classLevel, setClassLevel] = useState('');
  const [image, setImage] = useState(null);
  const [imagePreview, setImagePreview] = useState('');
  const [teacherClass, setTeacherClass] = useState([]);

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const currentUser = getAuth().currentUser;  // Assuming useAuth provides the current user

  useEffect(() => {
    const fetchTeacherData = async () => {
      try {
        const db = getFirestore();
        const teacherQuery = query(collection(db, 'Teachers'), where('id', '==', currentUser.uid));
        const teacherSnapshot = await getDocs(teacherQuery);
        const teacherData = teacherSnapshot.docs[0]?.data();

        if (teacherData) {
          setTeacherClass(teacherData.classTeacher);
        } else {
          setError('Teacher data not found');
        }
      } catch (error) {
        setError('Error fetching teacher data: ' + error.message);
      }
    };

    if (currentUser) {
      fetchTeacherData();
    }
  }, [currentUser]);

  const handleImageChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      setImage(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    setLoading(true);
    setSuccess(false);
    setError('');

    let imageUrl = '';

    if (image) {
      // Convert the image file to a blob
      const blobImage = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsArrayBuffer(image);
      });

      const metadata = {
        contentType: image.type,
      };
      const storage = getStorage();
      const storageRef = ref(storage, `profilePictures/${uuidv4()}`);
      const uploadTask = uploadBytesResumable(storageRef, blobImage, metadata);

      try {
        await new Promise((resolve, reject) => {
          uploadTask.on(
            'state_changed',
            null,
            (error) => {
              console.error('Error uploading image:', error);
              reject(error);
            },
            async () => {
              imageUrl = await getDownloadURL(uploadTask.snapshot.ref);
              resolve();
            }
          );
        });
      } catch (error) {
        setLoading(false);
        setError('Error uploading image: ' + error.message);
        return;
      }
    }

    const studentCode = uuidv4();
    const studentData = {
      name,
      dob,
      sex,
      address,
      contact,
      parentName,
      religiousAffiliation,
      dateOfAdmission,
      classLevel,
      image: imageUrl,
      code: studentCode,
      status: 'CurrentStudent'
    };

    const db = getFirestore();
    const q = query(collection(db, 'Students'), where('code', '==', studentCode));
    const querySnapshot = await getDocs(q);

    if (!querySnapshot.empty) {
      setLoading(false);
      setError('A student with this code already exists.');
      return;
    }

    try {
      await addDoc(collection(db, 'Students'), studentData);
      setSuccess(true);
    } catch (error) {
      setError('Error adding student: ' + error.message);
    } finally {
      setLoading(false);
      navigate(-1);
    }
  };

  const handleCloseSnackbar = () => {
    setSuccess(false);
    setError('');
  };

  return (
    <Container maxWidth="sm">
      <Typography variant="h4" gutterBottom>
        Add New Student
      </Typography>
      <form onSubmit={handleSubmit}>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <TextField
              label="Name"
              fullWidth
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Date of Birth"
              type="date"
              InputLabelProps={{ shrink: true }}
              fullWidth
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Sex</InputLabel>
              <Select
                value={sex}
                onChange={(e) => setSex(e.target.value)}
                required
              >
                <MenuItem value="Male">Male</MenuItem>
                <MenuItem value="Female">Female</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Digital Address"
              fullWidth
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Guardian/Parent Name"
              fullWidth
              value={parentName}
              onChange={(e) => setParentName(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Guardian/Parent Contact"
              fullWidth
              value={contact}
              onChange={(e) => setContact(e.target.value)}
              required
              type="number"
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Religious Affiliation"
              fullWidth
              value={religiousAffiliation}
              onChange={(e) => setReligiousAffiliation(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="Date of Admission"
              type="date"
              InputLabelProps={{ shrink: true }}
              fullWidth
              value={dateOfAdmission}
              onChange={(e) => setDateOfAdmission(e.target.value)}
              required
            />
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Class</InputLabel>
              <Select
                value={classLevel}
                onChange={(e) => setClassLevel(e.target.value)}
                required
              >
                <MenuItem value={teacherClass}>{teacherClass}</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <input
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              style={{ display: 'none' }}
              id="image-upload"
            />
            <label htmlFor="image-upload">
              <Button variant="contained" component="span">
                Upload Image
              </Button>
            </label>
            {imagePreview && (
              <Box sx={{ mt: 2 }}>
                <Typography variant="body2">Image Preview:</Typography>
                <ImagePreview src={imagePreview} alt="Preview" />
              </Box>
            )}
          </Grid>
          <Grid item xs={12}>
            <Button
              type="submit"
              variant="contained"
              color="primary"
              fullWidth
              disabled={loading}
            >
              {loading ? <CircularProgress size={24} /> : 'Add Student'}
            </Button>
          </Grid>
        </Grid>
      </form>
      <Snackbar
        open={success}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
      >
        <Alert onClose={handleCloseSnackbar} severity="success">
          Student added successfully!
        </Alert>
      </Snackbar>
      <Snackbar
        open={!!error}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
      >
        <Alert onClose={handleCloseSnackbar} severity="error">
          {error}
        </Alert>
      </Snackbar>
    </Container>
  );
}
