import { Card, CardActionArea, CardContent, CardMedia, Container, Grid, Typography } from '@mui/material';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import * as React from 'react';
import { useNavigate } from 'react-router-dom';

export default function Classes() {
  const [classesData, setClassesData] = React.useState([]);
  const navigate = useNavigate();

  React.useEffect(() => {
    const fetchStudentCounts = async () => {
      const db = getFirestore();
      const classes = ['KG 1', 'KG 2', 'Basic 1', 'Basic 2', 'Basic 3', 'Basic 4', 'Basic 5', 'Basic 6', 'Basic 7', 'Basic 8', 'Basic 9'];

      try {
        const classesWithCounts = await Promise.all(classes.map(async (className) => {
          const studentQuery = query(collection(db, 'Students'), where('classLevel', '==', className));
          const studentSnapshot = await getDocs(studentQuery);
          const studentCount = studentSnapshot.size;

          return { name: className, number: studentCount, image: 'https://via.placeholder.com/150' };
        }));

        setClassesData(classesWithCounts);
      } catch (error) {
        console.error('Error fetching student counts:', error);
      }
    };

    fetchStudentCounts();
  }, []);

  const handleCardClick = (className) => {
    navigate(`class/${className}`);
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Classes
      </Typography>
      <Grid container spacing={4}>
        {classesData.map((card) => (
          <Grid item xs={12} sm={6} md={3} key={card.name}>
            <Card>
              <CardActionArea onClick={() => handleCardClick(card.name)}>
                <CardMedia
                  component="img"
                  height="140"
                  image={card.image}
                  alt={card.name}
                />
                <CardContent>
                  <Typography variant="h6">{card.name}</Typography>
                  <Typography variant="body2" color="textSecondary">
                    {card.number}
                  </Typography>
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
}
