import {
  Box,
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Snackbar, // Add Snackbar
  TextField,
  Typography
} from '@mui/material';
import { getAuth } from 'firebase/auth';
import { collection, deleteDoc, doc, getDocs, getFirestore, query, updateDoc, where } from 'firebase/firestore';
import { getDownloadURL, getStorage, ref, uploadBytes } from 'firebase/storage';
import * as React from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';

export default function StudentDetail() {
  const { className, studentName } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const student = location.state?.student;

  const [openDialog, setOpenDialog] = React.useState(false);
  const [isClassTeacher, setIsClassTeacher] = React.useState(false);
  const [loading, setLoading] = React.useState(true);
  const [isEditing, setIsEditing] = React.useState(false);
  const [snackbarOpen, setSnackbarOpen] = React.useState(false);  // State for Snackbar

  // State for updating student information
  const [newName, setNewName] = React.useState(student?.name || '');
  const [newClassLevel, setNewClassLevel] = React.useState(student?.classLevel || '');
  const [newAddress, setNewAddress] = React.useState(student?.address || '');
  const [newContact, setNewContact] = React.useState(student?.contact || '');
  const [newsex, setNewSex] = React.useState(student?.sex || '');
  const [newDateOfBirth, setNewDateOfBirth] = React.useState(student?.dob || '');
  const [newImage, setNewImage] = React.useState(null); // For storing the new profile picture

  const handleOpenDialog = () => setOpenDialog(true);
  const handleCloseDialog = () => setOpenDialog(false);

  const handleOpenEditModal = () => setIsEditing(true);
  const handleCloseEditModal = () => setIsEditing(false);

  const handleSnackbarClose = () => setSnackbarOpen(false);  // Snackbar close function

  const handleImageChange = (e) => {
    setNewImage(e.target.files[0]); // Handle image file selection
  };

  const handleSaveChanges = async () => {
    try {
      const db = getFirestore();
      const studentRef = doc(db, 'Students', student.id);
      const updatedData = {
        name: newName,
        classLevel: newClassLevel,
        address: newAddress,
        contact: newContact,
        dob:newDateOfBirth,
        sex:newsex
      };

      // Upload new profile picture if selected
      if (newImage) {
        const storage = getStorage();
        const storageRef = ref(storage, `student_pics/${student.id}`);
        await uploadBytes(storageRef, newImage);
        const downloadUrl = await getDownloadURL(storageRef);
        updatedData.image = downloadUrl; // Set the new image URL
      }

      await updateDoc(studentRef, updatedData);
      
      // Show Snackbar when update is successful
      setSnackbarOpen(true);
    } catch (error) {
      console.error('Error updating student data:', error);
      alert('Failed to update student details.');
    }
    setIsEditing(false);
  };

  // Helper function to calculate age
  const calculateAge = (dob) => {
    const birthDate = new Date(dob);
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDifference = today.getMonth() - birthDate.getMonth();

    if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  React.useEffect(() => {
    const fetchTeacherData = async () => {
      const currentUser = getAuth().currentUser;

      if (currentUser) {
        const db = getFirestore();
        const q = query(collection(db, 'Teachers'), where('id', '==', currentUser.uid));
        const querySnapshot = await getDocs(q);

        querySnapshot.forEach((doc) => {
          const teacherData = doc.data();
          console.log(teacherData);
          setIsClassTeacher(
            teacherData.isClassTeacher && teacherData.classTeacher === student.classLevel
          );
        });
      }

      setLoading(false);
    };

    fetchTeacherData();
  }, [student]);

  const handleDelete = async () => {
    if (student) {
      try {
        const db = getFirestore();
        const studentRef = doc(db, 'Students', student.id);
        await deleteDoc(studentRef);
        navigate(-1); // Navigate back to the previous page
      } catch (error) {
        console.error('Error deleting student: ', error);
        alert('Failed to delete student. Please try again.');
      }
    }
    handleCloseDialog();
  };

  if (loading) {
    return (
      <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4">Loading...</Typography>
      </Container>
    );
  }

  if (!student) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Typography variant="h4">Student Details</Typography>
        <Typography variant="body1">No student data available.</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Box sx={{ textAlign: 'center', mb: 4 }}>
        <img
          src={student.image}
          alt={student.name}
          style={{
            width: 150,
            height: 150,
            borderRadius: '50%',
            marginBottom: '16px',
            border: '2px solid #ccc',
          }}
        />
        <Typography variant="h4" gutterBottom>
          {student.name}
        </Typography>
      </Box>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: 2,
          textAlign: 'left',
        }}
      >
        <Typography variant="h6">Age: {calculateAge(student.dob)}</Typography>
        <Typography variant="body1">Date of Birth: {new Date(student.dob).toLocaleDateString()}</Typography>
        <Typography variant="body1">Sex: {student.sex}</Typography>
        <Typography variant="body1">Address: {student.address}</Typography>
        <Typography variant="body1">Parent/Guardian: {student.parentName}</Typography>
        <Typography variant="body1">Contact: {student.contact}</Typography>
        <Typography variant="body1">Religious Affiliation: {student.religiousAffiliation}</Typography>
        <Typography variant="body1">Date of Admission: {new Date(student.dateOfAdmission).toLocaleDateString()}</Typography>
      </Box>
      {isClassTeacher && (
        <Box sx={{ textAlign: 'center', mt: 4 }}>
          <Button variant="contained" color="primary" onClick={handleOpenEditModal}>
            Edit
          </Button>
          <Button variant="contained" color="error" onClick={handleOpenDialog} sx={{ ml: 2 }}>
            Delete
          </Button>
        </Box>
      )}

      {/* Edit Modal */}
      <Dialog open={isEditing} onClose={handleCloseEditModal}>
        <DialogTitle>Edit Student Details</DialogTitle>
        <DialogContent>
          <TextField
            margin="dense"
            label="Name"
            fullWidth
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
          />
          <TextField
            margin="dense"
            label="Class Level"
            fullWidth
            value={newClassLevel}
            onChange={(e) => setNewClassLevel(e.target.value)}
          />
          <TextField
            margin="dense"
            label="Address"
            fullWidth
            value={newAddress}
            onChange={(e) => setNewAddress(e.target.value)}
          />
            <TextField
              label="Date of Birth"
              type="date"
              InputLabelProps={{ shrink: true }}
              fullWidth
              value={newDateOfBirth}
              onChange={(e) => setNewDateOfBirth(e.target.value)}
              required
            />
             <FormControl fullWidth>
              <InputLabel>Sex</InputLabel>
              <Select
                value={newsex}
                onChange={(e) => setNewSex(e.target.value)}
                required
              >
                <MenuItem value="Male">Male</MenuItem>
                <MenuItem value="Female">Female</MenuItem>
              </Select>
            </FormControl>
          <TextField
            margin="dense"
            label="Contact"
            fullWidth
            value={newContact}
            onChange={(e) => setNewContact(e.target.value)}
          />
          <input
            type="file"
            accept="image/*"
            onChange={handleImageChange}
            style={{ marginTop: '16px' }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseEditModal} color="secondary">
            Cancel
          </Button>
          <Button onClick={handleSaveChanges} color="primary">
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog}>
        <DialogTitle>Confirm Deletion</DialogTitle>
        <DialogContent>
          <Typography>Are you sure you want to delete this student? This action cannot be undone.</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog} color="secondary">
            Cancel
          </Button>
          <Button onClick={handleDelete} color="primary">
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for success notification */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={4000}
        onClose={handleSnackbarClose}
        message="Student details updated successfully"
      />
    </Container>
  );
}
