import FemaleIcon from '@mui/icons-material/Female';
import MaleIcon from '@mui/icons-material/Male';
import PeopleIcon from '@mui/icons-material/People';
import {
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { BarElement, CategoryScale, Chart as ChartJS, Legend, LinearScale, Title, Tooltip } from 'chart.js';
import { collection, getDocs, getFirestore } from 'firebase/firestore';
import { useEffect, useState } from 'react';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const CardStyled = styled(Card)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  padding: theme.spacing(2),
}));

export default function Home() {
  const [students, setStudents] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [classCounts, setClassCounts] = useState({});

  useEffect(() => {
    const fetchData = async () => {
      const db = getFirestore();

      // Fetch students
      const studentsSnapshot = await getDocs(collection(db, 'Students'));
      const studentsData = studentsSnapshot.docs.map(doc => doc.data());
      setStudents(studentsData);

      // Fetch teachers
      const teachersSnapshot = await getDocs(collection(db, 'Teachers'));
      const teachersData = teachersSnapshot.docs.map(doc => doc.data());
      setTeachers(teachersData);

      // Calculate class counts
      const classCounts = studentsData.reduce((acc, student) => {
        const { classLevel } = student;
        if (!acc[classLevel]) {
          acc[classLevel] = { male: 0, female: 0, total: 0 };
        }
        acc[classLevel].total += 1;
        if (student.sex === 'Male') {
          acc[classLevel].male += 1;
        } else if (student.sex === 'Female') {
          acc[classLevel].female += 1;
        }
        return acc;
      }, {});

      setClassCounts(classCounts);
    };

    fetchData();
  }, []);

  const totalStudents = students.length;
  const totalTeachers = teachers.length;

  // Prepare data for the bar chart
  const chartData = {
    labels: Object.keys(classCounts),
    datasets: [
      {
        label: 'Total Students',
        data: Object.values(classCounts).map(count => count.total),
        backgroundColor: 'rgba(75, 192, 192, 0.6)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 1,
      },
    ],
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Grid container spacing={3}>
        {/* Cards */}
        <Grid item xs={12} md={4}>
          <CardStyled>
            <PeopleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Total Students</Typography>
              <Typography variant="h6">{totalStudents}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
        <Grid item xs={12} md={4}>
          <CardStyled>
            <MaleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Total Male</Typography>
              <Typography variant="h6">{students.filter(student => student.sex === 'Male').length}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
        <Grid item xs={12} md={4}>
          <CardStyled>
            <FemaleIcon fontSize="large" color="primary" />
            <CardContent>
              <Typography variant="h4">Total Female</Typography>
              <Typography variant="h6">{students.filter(student => student.sex === 'Female').length}</Typography>
            </CardContent>
          </CardStyled>
        </Grid>
      </Grid>

      {/* Conditional rendering of chart or table */}
      {Object.keys(classCounts).length > 1 ? (
        <Box sx={{ mt: 4 }}>
          <Typography variant="h5" gutterBottom>
            Students Distribution by Class
          </Typography>
          <Bar data={chartData} />
        </Box>
      ) : (
        <Box sx={{ mt: 4 }}>
          <Paper>
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Class</TableCell>
                    <TableCell align="right">Male</TableCell>
                    <TableCell align="right">Female</TableCell>
                    <TableCell align="right">Total</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {Object.keys(classCounts).map((className) => (
                    <TableRow key={className}>
                      <TableCell component="th" scope="row">
                        {className}
                      </TableCell>
                      <TableCell align="right">{classCounts[className].male}</TableCell>
                      <TableCell align="right">{classCounts[className].female}</TableCell>
                      <TableCell align="right">{classCounts[className].total}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Box>
      )}
    </Container>
  );
}
