import {
  Box,
  Button,
  Container,
  Divider,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Typography,
} from '@mui/material';
import { getAuth } from 'firebase/auth';
import { collection, getDocs, getFirestore, query, where } from 'firebase/firestore';
import * as React from 'react';
import { useNavigate } from 'react-router-dom';
import './ClassDetailStyles.css'; // Import the external style file

const ITEMS_PER_PAGE = 10; // Define how many items to show per page

export default function Grades() {
  const navigate = useNavigate();
  const currentUser = getAuth().currentUser; // Get the current user
  
  const [searchTerm, setSearchTerm] = React.useState('');
  const [sortBy, setSortBy] = React.useState('');
  const [students, setStudents] = React.useState([]);
  const [filteredStudents, setFilteredStudents] = React.useState([]);
  const [teacherClasses, setTeacherClasses] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
  
  // Pagination state
  const [currentPage, setCurrentPage] = React.useState(1);

  // Helper function to calculate age from date of birth
  const calculateAge = (dob) => {
    const birthDate = new Date(dob);
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();

    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  // Fetch the current teacher's data and students data from Firestore
  React.useEffect(() => {
    const fetchTeacherAndStudents = async () => {
      setLoading(true);
      try {
        const db = getFirestore();

        // Fetch the current teacher's data
        const teacherQuery = query(collection(db, 'Teachers'), where('id', '==', currentUser.uid));
        const teacherSnapshot = await getDocs(teacherQuery);
        const teacherData = teacherSnapshot.docs[0]?.data();

        if (!teacherData) {
          throw new Error('Teacher data not found');
        }

        // Set the teacher's classes
        setTeacherClasses(teacherData.classes || []);

        // Fetch students from the classes the teacher teaches
        const studentQuery = query(collection(db, 'Students'), where('classLevel', 'in', teacherData.classes));
        const studentSnapshot = await getDocs(studentQuery);
        const studentsList = studentSnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
        
        setStudents(studentsList);
        setFilteredStudents(studentsList);
      } catch (err) {
        setError('Please Refresh: ' + (err.message || 'Unknown error'));
      } finally {
        setLoading(false);
      }
    };

    fetchTeacherAndStudents();
  }, [currentUser]);

  React.useEffect(() => {
    let sortedStudents = students.filter((student) =>
      student.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (sortBy) {
      sortedStudents = sortedStudents.sort((a, b) => {
        if (sortBy === 'name') {
          return a.name.localeCompare(b.name);
        } else if (sortBy === 'age') {
          return calculateAge(a.dob) - calculateAge(b.dob);
        } else if (sortBy === 'classLevel') {
          const classOrder = {
            'KG 1': 1,
            'KG 2': 2,
            'Basic 1': 3,
            'Basic 2': 4,
            'Basic 3': 5,
            'Basic 4': 6,
            'Basic 5': 7,
            'Basic 6': 8,
            'Basic 7': 9,
            'Basic 8': 10,
            'Basic 9': 11,
          };
          return classOrder[a.classLevel] - classOrder[b.classLevel];
        }
        return 0;
      });
    }

    setFilteredStudents(sortedStudents);
  }, [searchTerm, sortBy, students]);

  const handleGradeStudent = (student) => {
    const encodedName = encodeURIComponent(student.name);
    navigate(`add/${encodedName}`, {
      state: { student, code: student.code },
    });
  };

  const handleSortChange = (event) => {
    setSortBy(event.target.value);
  };

  const handleClassFilter = (classLevel) => {
    setFilteredStudents(students.filter(student => student.classLevel === classLevel));
    setCurrentPage(1); // Reset to the first page when filtering
  };

  const totalPages = Math.ceil(filteredStudents.length / ITEMS_PER_PAGE);
  const paginatedStudents = filteredStudents.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={4}>
        <Typography variant="h4">MY Students</Typography>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel>Sort By</InputLabel>
          <Select value={sortBy} onChange={handleSortChange} label="Sort By">
            <MenuItem value="">None</MenuItem>
            <MenuItem value="name">Name</MenuItem>
            <MenuItem value="age">Age</MenuItem>
            <MenuItem value="classLevel">Class Level</MenuItem>
          </Select>
        </FormControl>
      </Box>

      <Box display="block" justifyContent="space-between" mb={4} width="100%">
        <TextField
          variant="outlined"
          placeholder="Search by name"
          fullWidth
          sx={{ mb: 4 }}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <Box display="flex" alignItems="center">
          {teacherClasses.map((classLevel) => (
            <Button
              key={classLevel}
              variant="outlined"
              onClick={() => handleClassFilter(classLevel)}
              sx={{ ml: 1 }}
            >
              {classLevel}
            </Button>
          ))}
        </Box>
      </Box>

      {loading ? (
        <Typography variant="h6">Loading...</Typography>
      ) : error ? (
        <Typography variant="h6" color="error">
          {error}
        </Typography>
      ) : (
        <div className="student-list">
          {paginatedStudents.map((student) => (
            <div className="student-item" key={student.id}>
              <img
                className="student-image"
                src={student.image || 'https://via.placeholder.com/100'}
                alt={student.name}
              />
              <div className="student-content">
                <Typography variant="h6">{student.name}</Typography>
                <Typography variant="body2" color="textSecondary">
                  Age: {calculateAge(student.dob)}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Date of Birth: {new Date(student.dob).toLocaleDateString()}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Class: {student.classLevel}
                </Typography>
                <Divider sx={{ my: 2 }} />
              </div>
              <div className="student-buttons">
                <Button
                  variant="contained"
                  color="primary"
                  onClick={() => handleGradeStudent(student)}
                >
                  Grade Student
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
      <Box display="flex" justifyContent="center" mt={4}>
        <Button
          disabled={currentPage === 1}
          onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
        >
          Previous
        </Button>
        <Typography sx={{ mx: 2 }}>{`Page ${currentPage} of ${totalPages}`}</Typography>
        <Button
          disabled={currentPage === totalPages}
          onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
        >
          Next
        </Button>
      </Box>
    </Container>
  );
}
